package com.tencent.weknora.model.client;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.Consumer;

/** Native Go Responses protocol: ordered input/reasoning replay, response DTO and typed SSE. */
public final class OpenAIResponses implements ChatModel {
    private static final ObjectMapper JSON=SafeModelHttp.JSON;
    private static final List<String> LADDER=List.of("minimal","low","medium","high","xhigh","max");
    private static final String REASONING="openai_responses_reasoning",CALL_ITEM="openai_responses_item_id";
    private final SafeModelHttp http;private final ModelEndpoint endpoint;private final Duration chatTimeout,streamTimeout;
    public OpenAIResponses(SafeModelHttp http,ModelEndpoint endpoint,Duration chatTimeout,Duration streamTimeout){this.http=http;this.endpoint=endpoint;this.chatTimeout=chatTimeout;this.streamTimeout=streamTimeout;}
    @Override public String modelId(){return endpoint.id;}@Override public String modelName(){return endpoint.name;}
    private boolean flag(String name){return endpoint.settings.path(name).asBoolean();}
    public ObjectNode request(List<ObjectNode> messages,ObjectNode opts,boolean stream){
        ObjectNode body=JSON.createObjectNode().put("model",endpoint.wireModel);ArrayNode input=JSON.createArrayNode();List<String> instructions=new ArrayList<>();
        for(ObjectNode message:messages){String role=message.path("role").asText(),text=neutralize(message.path("content").asText());switch(role){
            case "system":if(!text.isEmpty())instructions.add(text);break;
            case "assistant":{
                JsonNode prior=message.path("reasoning_metadata").get(REASONING);if(prior!=null&&prior.isArray())prior.forEach(item->{if(!item.isNull())input.add(item.deepCopy());});
                if(!text.isEmpty()||message.path("tool_calls").isEmpty()){ObjectNode part=JSON.createObjectNode().put("type","output_text");if(!text.isEmpty())part.put("text",text);input.add(JSON.createObjectNode().put("type","message").put("role","assistant").set("content",JSON.createArrayNode().add(part)));}
                for(JsonNode call:message.path("tool_calls")){ObjectNode item=JSON.createObjectNode().put("type","function_call").put("call_id",call.path("id").asText()).put("name",call.path("function").path("name").asText()).put("arguments",neutralize(call.path("function").path("arguments").asText()));if(call.path("provider_metadata").hasNonNull(CALL_ITEM))item.set("id",call.path("provider_metadata").get(CALL_ITEM).deepCopy());input.add(item);}break;
            }
            case "tool":input.add(JSON.createObjectNode().put("type","function_call_output").put("call_id",message.path("tool_call_id").asText()).put("output",text));break;
            default:input.add(JSON.createObjectNode().put("type","message").put("role","user").set("content",userContent(message,text)));
        }}body.set("input",input);if(!instructions.isEmpty())body.put("instructions",String.join("\n\n",instructions));if(stream)body.put("stream",true);if(flag("supports_store"))body.put("store",false);
        if(opts!=null){if(flag("supports_temperature")&&!endpoint.reasoning)for(String key:List.of("temperature","top_p"))if(opts.path(key).asDouble()>0)body.set(key,opts.get(key));int budget=opts.path("max_completion_tokens").asInt();if(budget<=0)budget=opts.path("max_tokens").asInt();if(budget>0&&flag("supports_max_output_tokens"))body.put("max_output_tokens",Math.max(16,budget));tools(body,opts);
            if(opts.has("format")){body.set("text",JSON.createObjectNode().set("format",JSON.createObjectNode().put("type","json_object")));appendSchema(input,"\nUse this JSON schema: "+opts.get("format"));}
            if(flag("prompt_cache_key")&&!opts.path("cache_retention").asText().equals("none")){String key=clampKey(opts.path("prompt_cache_key").asText());if(!key.isEmpty()){body.put("prompt_cache_key",key);if(opts.path("cache_retention").asText().equals("long")&&flag("supports_long_cache_retention"))body.put("prompt_cache_retention","24h");}}
        }reasoning(body,opts);endpoint.settings.path("extra_body").fields().forEachRemaining(e->{if(!body.has(e.getKey()))body.set(e.getKey(),e.getValue().deepCopy());});return body;
    }
    private static JsonNode userContent(ObjectNode m,String text){ArrayNode parts=JSON.createArrayNode();if(!m.path("multi_content").isEmpty()){for(JsonNode part:m.path("multi_content")){String type=part.path("type").asText();if(type.equals("text")){ObjectNode out=JSON.createObjectNode().put("type","input_text");String value=neutralize(part.path("text").asText());if(!value.isEmpty())out.put("text",value);parts.add(out);}else if(type.equals("image_url")&&part.hasNonNull("image_url")){JsonNode image=part.get("image_url");parts.add(JSON.createObjectNode().put("type","input_image").put("image_url",imageURL(image.path("url").asText())).put("detail",fallback(image.path("detail").asText(),"auto")));}}return parts;}
        if(!m.path("images").isEmpty()){for(JsonNode image:m.path("images"))parts.add(JSON.createObjectNode().put("type","input_image").put("image_url",imageURL(image.asText())).put("detail","auto"));ObjectNode out=JSON.createObjectNode().put("type","input_text");if(!text.isEmpty())out.put("text",text);parts.add(out);return parts;}return TextNode.valueOf(text);
    }
    private static String imageURL(String url){if(!url.startsWith("http://")&&!url.startsWith("https://")&&!url.startsWith("data:"))throw new ModelClientException("Native chat requires an absolute HTTP or data image URL; storage image resolution is not migrated");return url;}
    private static void appendSchema(ArrayNode input,String suffix){for(int i=input.size()-1;i>=0;i--){JsonNode candidate=input.get(i);if(!candidate.isObject())continue;ObjectNode item=(ObjectNode)candidate;if(!item.path("type").asText().equals("message")||!item.path("role").asText().equals("user"))continue;JsonNode content=item.get("content");if(content.isTextual())item.put("content",content.asText()+suffix);else if(content.isArray()){ArrayNode parts=(ArrayNode)content;for(int j=parts.size()-1;j>=0;j--)if(parts.get(j).path("type").asText().equals("input_text")){((ObjectNode)parts.get(j)).put("text",parts.get(j).path("text").asText()+suffix);return;}parts.add(JSON.createObjectNode().put("type","input_text").put("text",suffix.startsWith("\n")?suffix.substring(1):suffix));}return;}}
    private void tools(ObjectNode body,ObjectNode opts){if(opts.path("tools").isEmpty())return;ArrayNode tools=JSON.createArrayNode();for(JsonNode tool:opts.path("tools")){JsonNode function=tool.path("function");ObjectNode entry=JSON.createObjectNode().put("type",fallback(tool.path("type").asText(),"function")).put("name",function.path("name").asText()).put("description",function.path("description").asText());if(function.hasNonNull("parameters"))entry.set("parameters",function.get("parameters").deepCopy());tools.add(entry);}body.set("tools",tools);if(opts.hasNonNull("parallel_tool_calls")&&flag("supports_parallel_tool_calls"))body.set("parallel_tool_calls",opts.get("parallel_tool_calls"));String choice=opts.path("tool_choice").asText();if(!choice.isEmpty())body.set("tool_choice",Set.of("auto","none","required").contains(choice)?TextNode.valueOf(choice):JSON.createObjectNode().put("type","function").put("name",choice));}
    private void reasoning(ObjectNode body,ObjectNode opts){String level=level(opts);if(!level.isEmpty()){if(!level.equals("off")){level=clampLevel(level);ObjectNode reasoning=JSON.createObjectNode();if(LADDER.contains(level))reasoning.put("effort",endpoint.thinking.hasNonNull(level)?endpoint.thinking.path(level).asText():level);if(flag("supports_reasoning_summary"))reasoning.put("summary","auto");if(!reasoning.isEmpty())body.set("reasoning",reasoning);}else if(endpoint.thinking.hasNonNull("off")&&!endpoint.thinking.path("off").asText().isEmpty())body.set("reasoning",JSON.createObjectNode().put("effort",endpoint.thinking.path("off").asText()));}if(endpoint.reasoning&&flag("supports_encrypted_reasoning"))body.set("include",JSON.createArrayNode().add("reasoning.encrypted_content"));}
    private boolean supports(String level){return endpoint.thinking.has(level)?!endpoint.thinking.get(level).isNull():!Set.of("xhigh","max").contains(level);}
    private String clampLevel(String level){if(!LADDER.contains(level)||supports(level))return level;int at=LADDER.indexOf(level);for(int i=at+1;i<LADDER.size();i++)if(supports(LADDER.get(i)))return LADDER.get(i);for(int i=at-1;i>=0;i--)if(supports(LADDER.get(i)))return LADDER.get(i);return "auto";}
    private static String level(ObjectNode opts){if(opts==null)return "";String value=opts.path("reasoning_effort").asText();if(Set.of("none","false","disabled").contains(value))return "off";if(Set.of("true","enabled","default","on").contains(value))return "auto";if(value.equals("off")||value.equals("auto")||LADDER.contains(value))return value;return opts.hasNonNull("thinking")?(opts.path("thinking").asBoolean()?"auto":"off"):"";}
    private static String neutralize(String text){String[][]tokens={{"<|","<\u200b|"},{"<｜","<\u200b｜"},{"<start_of_turn>","<\u200bstart_of_turn>"},{"<end_of_turn>","<\u200bend_of_turn>"},{"[INST]","[\u200bINST]"},{"[/INST]","[\u200b/INST]"},{"<<SYS>>","<\u200b<SYS>>"},{"<</SYS>>","<\u200b</SYS>>"}};for(String[] token:tokens)text=text.replace(token[0],token[1]);return text;}
    private static String fallback(String value,String other){return value.isEmpty()?other:value;}
    private static String clampKey(String key){int count=key.codePointCount(0,key.length());return count<=64?key:key.substring(0,key.offsetByCodePoints(0,64));}
    private Map<String,String> headers(ObjectNode opts,boolean stream){var headers=endpoint.headers(stream);if(flag("prompt_cache_key")&&opts!=null){String key=clampKey(opts.path("prompt_cache_key").asText());if(!key.isEmpty())for(String name:List.of("session_id","x-client-request-id","x-session-affinity"))headers.put(name,key);}return headers;}
    private SafeModelHttp.Response sendOnce(CallContext call,List<ObjectNode> messages,ObjectNode opts,boolean stream){Duration timeout=call.deadline()==null?(stream?streamTimeout:chatTimeout):Duration.ZERO;SafeModelHttp.Response response=http.post(call,endpoint.url,headers(opts,stream),request(messages,opts,stream).toString().getBytes(StandardCharsets.UTF_8),timeout);if(response.status()<200||response.status()>=300){try(response){throw new ModelHttpException(response.status(),response.text(1<<20),endpoint);}}return response;}
    private SafeModelHttp.Response send(CallContext call,List<ObjectNode> messages,ObjectNode opts,boolean stream){ObjectNode effective=ChatInputs.options(call,opts);try{return sendOnce(call,messages,effective,stream);}catch(ModelHttpException ex){if(!ex.retryWithoutImages())throw ex;return sendOnce(call,ChatInputs.stripImages(messages),effective,stream);}}
    @Override public ObjectNode chat(CallContext call,List<ObjectNode> messages,ObjectNode opts){try(var response=send(call,messages,opts,false)){return decode(JSON.readTree(response.bytes(64<<20)));}catch(IOException ex){throw new ModelClientException("decode response: invalid JSON");}}
    public ObjectNode decode(JsonNode env){validateResponse(env);if(!text(env.path("error"),"message").isEmpty())throw new ModelClientException(endpoint.safe("API error: "+text(env.path("error"),"message")));if(text(env,"status").equals("failed"))throw new ModelClientException("API error: response failed");List<String> content=new ArrayList<>(),summaries=new ArrayList<>();ArrayNode reasoning=JSON.createArrayNode(),tools=JSON.createArrayNode();JsonNode output=env.path("output");if(!output.isMissingNode()&&!output.isNull()&&!output.isArray())throw new ModelClientException("decode response: output must be an array");for(JsonNode item:output){if(item.isNull())continue;validateItem(item);switch(text(item,"type")){case "message":content.add(itemText(item,"content",true));break;case "reasoning":String summary=itemText(item,"summary",false);if(!summary.isEmpty())summaries.add(summary);reasoning.add(item.deepCopy());break;case "function_call":tools.add(tool(item));break;}}ObjectNode result=JSON.createObjectNode().put("content",String.join("",content));if(!summaries.isEmpty())result.put("reasoning_content",String.join("\n",summaries));if(!reasoning.isEmpty())result.set("reasoning_metadata",JSON.createObjectNode().set(REASONING,reasoning));if(!tools.isEmpty())result.set("tool_calls",tools);result.put("finish_reason",finish(env,!tools.isEmpty()));result.set("usage",usage(env.path("usage")));return result;}
    private static String itemText(JsonNode item,String field,boolean onlyOutput){JsonNode parts=item.path(field);if(parts.isMissingNode()||parts.isNull())return "";if(!parts.isArray())throw new ModelClientException("decode output item: "+field+" must be an array");List<String> values=new ArrayList<>();for(JsonNode part:parts){if(part.isNull())continue;requireObject(part,"output part");if(!onlyOutput||text(part,"type").equals("output_text")){String value=text(part,"text");if(onlyOutput||!value.isEmpty())values.add(value);}}return String.join(onlyOutput?"":"\n",values);}
    private static ObjectNode tool(JsonNode item){ObjectNode out=JSON.createObjectNode().put("id",text(item,"call_id")).put("type","function");out.set("function",JSON.createObjectNode().put("name",text(item,"name")).put("arguments",text(item,"arguments")));if(item.hasNonNull("id"))out.set("provider_metadata",JSON.createObjectNode().set(CALL_ITEM,item.get("id").deepCopy()));return out;}
    private static String finish(JsonNode env,boolean tools){if(tools)return "tool_calls";if(text(env,"status").equals("incomplete"))switch(text(env.path("incomplete_details"),"reason")){case "max_output_tokens":return "length";case "content_filter":return "content_filter";}return "stop";}
    public static ObjectNode usage(JsonNode source){ObjectNode common=JSON.createObjectNode().put("prompt_tokens",integer(source,"input_tokens")).put("completion_tokens",integer(source,"output_tokens")).put("total_tokens",integer(source,"total_tokens"));if(source.path("input_tokens_details").isObject())common.set("prompt_tokens_details",JSON.createObjectNode().put("cached_tokens",integer(source.path("input_tokens_details"),"cached_tokens")));return OpenAIChat.usage(common,true);}
    private static int integer(JsonNode n,String key){JsonNode value=n.get(key);if(value==null||value.isNull())return 0;if(!value.isIntegralNumber()||!value.canConvertToInt())throw new ModelClientException("decode response: "+key+" must be an integer");return value.asInt();}
    private static String text(JsonNode n,String key){JsonNode value=n.get(key);if(value==null||value.isNull())return "";if(!value.isTextual())throw new ModelClientException("decode response: "+key+" must be a string");return value.asText();}
    private static void validateResponse(JsonNode n){
        if(n==null||n.isNull())return;requireObject(n,"response");for(String k:List.of("id","status"))text(n,k);
        if(n.hasNonNull("error")){requireObject(n.get("error"),"error");text(n.get("error"),"message");}
        if(n.hasNonNull("incomplete_details")){requireObject(n.get("incomplete_details"),"incomplete_details");text(n.get("incomplete_details"),"reason");}
        if(n.hasNonNull("output")&&!n.get("output").isArray())throw new ModelClientException("decode response: output must be an array");
        if(n.hasNonNull("usage")){JsonNode usage=n.get("usage");requireObject(usage,"usage");for(String k:List.of("input_tokens","output_tokens","total_tokens"))integer(usage,k);if(usage.hasNonNull("input_tokens_details")){requireObject(usage.get("input_tokens_details"),"input_tokens_details");integer(usage.get("input_tokens_details"),"cached_tokens");}}
    }
    private static void validateItem(JsonNode n){
        if(n==null||n.isNull())return;requireObject(n,"output item");for(String k:List.of("type","status","role","call_id","name","arguments"))text(n,k);
        for(String k:List.of("content","summary")){JsonNode parts=n.get(k);if(parts==null||parts.isNull())continue;if(!parts.isArray())throw new ModelClientException("decode output item: "+k+" must be an array");for(JsonNode part:parts){if(part.isNull())continue;requireObject(part,"output part");text(part,"type");text(part,"text");}}
    }
    private static void requireObject(JsonNode n,String label){if(n==null||!n.isObject())throw new ModelClientException("decode "+label+": expected object");}
    private static String line(InputStream in)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();while(true){int c=in.read();if(c<0){if(bytes.size()==0)return null;break;}if(c=='\n')break;if(bytes.size()>=1<<20)throw new ModelClientException("Stream line exceeds Go SSE maximum size");bytes.write(c);}byte[] raw=bytes.toByteArray();int length=raw.length;if(length>0&&raw[length-1]=='\r')length--;return new String(raw,0,length,StandardCharsets.UTF_8);}
    private static String key(JsonNode item,int index){String id=item.path("id").isTextual()?item.path("id").asText():"";return id.isEmpty()?"output_index:"+index:id;}
    private static ObjectNode callMetadata(JsonNode item){return item.hasNonNull("id")?JSON.createObjectNode().set(CALL_ITEM,item.get("id").deepCopy()):null;}
    @Override public void stream(CallContext call,List<ObjectNode> messages,ObjectNode opts,Consumer<ObjectNode> consumer){try(var response=send(call,messages,opts,true)){ModelStreamAssembler assembler=new ModelStreamAssembler(call,consumer,endpoint);Map<String,Integer> toolIndex=new HashMap<>();Set<String> argsSeen=new HashSet<>();ArrayNode reasoningItems=JSON.createArrayNode();try{
        while(true){call.check();String raw=line(response.body());if(raw==null){finishEOF(assembler,reasoningItems);return;}if(!raw.startsWith("data:"))continue;String payload=raw.substring(5);if(payload.startsWith(" "))payload=payload.substring(1);if(payload.strip().equals("[DONE]")){finishEOF(assembler,reasoningItems);return;}if(payload.isEmpty())continue;JsonNode event;try{event=JSON.readTree(payload);}catch(IOException ex){throw new ModelClientException("decode stream chunk: invalid JSON");}if(event==null||event.isNull())continue;requireObject(event,"stream chunk");for(String field:List.of("type","delta","item_id","message"))text(event,field);integer(event,"summary_index");if(event.hasNonNull("response"))validateResponse(event.get("response"));String type=text(event,"type");int outputIndex=integer(event,"output_index");JsonNode item=event.path("item");if((type.equals("response.output_item.added")||type.equals("response.output_item.done"))&&!item.isMissingNode()&&!item.isNull())validateItem(item);
            switch(type){
                case "response.output_text.delta":assembler.process("",text(event,"delta"),List.of(),"");break;
                case "response.reasoning_summary_text.delta":case "response.reasoning_text.delta":assembler.process(text(event,"delta"),"",List.of(),"");break;
                case "response.reasoning_summary_part.added":if(integer(event,"summary_index")>0)assembler.process("\n","",List.of(),"");break;
                case "response.output_item.added":if(text(item,"type").equals("function_call")){String key=key(item,outputIndex);int index=toolIndex.computeIfAbsent(key,k->toolIndex.size());assembler.process("","",List.of(new ModelStreamAssembler.ToolDelta(index,text(item,"call_id"),"function",text(item,"name"),"")),"");assembler.metadata(index,callMetadata(item));}break;
                case "response.function_call_arguments.delta":{String delta=text(event,"delta");if(!delta.isEmpty()){String key=text(event,"item_id");if(key.isEmpty())key="output_index:"+outputIndex;argsSeen.add(key);int index=toolIndex.computeIfAbsent(key,k->toolIndex.size());assembler.process("","",List.of(new ModelStreamAssembler.ToolDelta(index,"","","",delta)),"");}break;}
                case "response.output_item.done":switch(text(item,"type")){case "reasoning":reasoningItems.add(item.deepCopy());break;case "function_call":String key=key(item,outputIndex),arguments=text(item,"arguments");if(!argsSeen.contains(key)&&!arguments.isEmpty()){argsSeen.add(key);int index=toolIndex.computeIfAbsent(key,k->toolIndex.size());assembler.process("","",List.of(new ModelStreamAssembler.ToolDelta(index,text(item,"call_id"),"function",text(item,"name"),arguments)),"");assembler.metadata(index,callMetadata(item));}break;}break;
                case "response.completed":case "response.incomplete":{JsonNode finalResponse=event.path("response");if(!finalResponse.isMissingNode()&&!finalResponse.isNull())requireObject(finalResponse,"response");if(finalResponse.hasNonNull("usage"))assembler.usage(usage(finalResponse.get("usage")));if(reasoningItems.isEmpty()&&finalResponse.path("output").isArray())for(JsonNode out:finalResponse.path("output"))if(out.isObject()&&out.path("type").asText().equals("reasoning")){try{validateItem(out);reasoningItems.add(out.deepCopy());}catch(ModelClientException ignored){}}String reason=finish(finalResponse,assembler.toolCount()>0);if(type.equals("response.incomplete")&&reason.equals("stop"))reason="length";assembler.process("","",List.of(),reason);if(!reasoningItems.isEmpty())assembler.reasoning(JSON.createObjectNode().set(REASONING,reasoningItems));assembler.end();return;}
                case "response.failed":throw new ModelClientException(endpoint.safe("API stream error: "+fallback(text(event.path("response").path("error"),"message"),"response failed")));
                case "error":throw new ModelClientException(endpoint.safe("API stream error: "+fallback(text(event,"message"),"unknown error")));
            }
        }
    }catch(CancellationException ex){throw ex;}catch(IOException|ModelClientException ex){call.check();assembler.fail(ex.getMessage());}}}
    private static void finishEOF(ModelStreamAssembler assembler,ArrayNode reasoning){if(!reasoning.isEmpty())assembler.reasoning(JSON.createObjectNode().set(REASONING,reasoning));assembler.endAtEOF();}
}
